const settings = $input.first().json;
const markets = String(settings.markets || '')
  .split(',')
  .map((market) => market.trim())
  .filter(Boolean);

if (markets.length === 0) {
  throw new Error('Opportunity radar settings has no markets. Put at least one market in markets, separated by commas.');
}

return markets.map((market) => ({
  json: {
    market,
    stages: settings.stages,
    minAmountUsd: settings.minAmountUsd,
    lookbackDays: settings.lookbackDays,
    articleCount: settings.articleCount,
  },
}));

parameters.text:
=You are qualifying recently funded startups in one investment market: {{ $json.market }}

Call the Webz.io news search tool exactly once, with these arguments:

- query: startup raises funding round {{ $json.stages }} {{ $json.market }}
- days: {{ $json.lookbackDays }}
- language: ["english"]
- k: {{ $json.articleCount }}

Do not pass any other filters.

From the returned articles, extract announced and completed venture equity rounds relevant to this market. Include seed, Series A/B/C, growth, and strategic equity rounds matching the stages when possible.

Exclude rumors, companies merely seeking funding, IPOs, debt, loans, grants, acquisitions, and roundup articles without a dedicated round announcement.

For each opportunity return company, round_type, amount_usd (0 if undisclosed), investors, company_description, reason_to_watch, headline, publisher, announced date, and url. `reason_to_watch` must be one concise, evidence-based sentence grounded in the article — never invent product claims or market fit. Set market to {{ $json.market }}.

If nothing qualifies, return an empty opportunities array.

