const settings = $('Opportunity radar settings').first().json;
const staticData = $getWorkflowStaticData('global');
const seen = new Set(Array.isArray(staticData.seenOpportunities) ? staticData.seenOpportunities : []);
const clean = (value) => String(value ?? '').replace(/[<>|]/g, '').trim();
const minAmount = Number(settings.minAmountUsd) || 0;

const roundLabels = {
  pre_seed: 'Pre-seed', seed: 'Seed', series_a: 'Series A', series_b: 'Series B',
  series_c: 'Series C', series_d_plus: 'Series D+', growth: 'Growth',
  strategic: 'Strategic', undisclosed: 'Undisclosed',
};
const formatAmount = (amount) => {
  const n = Number(amount);
  if (!n || n <= 0) return 'undisclosed amount';
  if (n >= 1000000000) return '$' + (n / 1000000000).toFixed(1).replace(/\.0$/, '') + 'B';
  if (n >= 1000000) return '$' + Math.round(n / 1000000) + 'M';
  return '$' + n.toLocaleString();
};
const normalizedCompany = (name) => clean(name).toLowerCase().replace(/[^a-z0-9]/g, '');
const keyFor = (company, roundType) => normalizedCompany(company) + '|' + String(roundType || 'undisclosed').toLowerCase();

const opportunities = [];
const seenThisRun = new Set();
const sectionsByMarket = {};
for (const item of $input.all()) {
  const output = item.json.output || {};
  const market = clean(output.market) || 'Startup opportunities';
  const candidates = Array.isArray(output.opportunities) ? output.opportunities : [];
  for (const candidate of candidates) {
    const company = clean(candidate.company);
    const roundType = candidate.round_type || 'undisclosed';
    const amount = Number(candidate.amount_usd) || 0;
    const url = String(candidate.url ?? '').trim();
    if (!company || !url || (amount > 0 && amount < minAmount)) continue;
    const key = keyFor(company, roundType);
    if (seen.has(key) || seenThisRun.has(key)) continue;
    seen.add(key);
    seenThisRun.add(key);
    const opportunity = {
      company, round_type: roundType, amount_usd: amount,
      investors: clean(candidate.investors), market,
      reason_to_watch: clean(candidate.reason_to_watch),
      company_description: clean(candidate.company_description),
      headline: clean(candidate.headline) || company + ' funding',
      publisher: clean(candidate.publisher), announced: clean(candidate.announced), url,
    };
    opportunities.push(opportunity);
    let line = '• *' + company + '* — ' + (roundLabels[roundType] || roundType) + ', ' + formatAmount(amount);
    if (opportunity.investors) line += ' (investors: ' + opportunity.investors + ')';
    line += '\n  ' + (opportunity.reason_to_watch || 'Review the funding announcement.') + ' — <' + url + '|' + opportunity.headline + '>';
    if (!sectionsByMarket[market]) sectionsByMarket[market] = [];
    sectionsByMarket[market].push(line);
  }
}
staticData.seenOpportunities = Array.from(seen).slice(-1000);
const sections = Object.entries(sectionsByMarket).map(([market, lines]) => '*' + market + '*\n' + lines.join('\n'));
return [{ json: {
  hasNew: opportunities.length > 0,
  opportunities,
  alertText: ':dart: *New startup opportunities*\n\n' + sections.join('\n\n'),
  slackChannel: settings.slackChannel,
} }];

const foundAt = new Date().toISOString();
const opportunities = Array.isArray($input.first().json.opportunities) ? $input.first().json.opportunities : [];
return opportunities.map((opportunity) => ({ json: { found_at: foundAt, ...opportunity } }));
